import 'dart:io';
import 'package:image/image.dart';
import 'package:barcode_image/barcode_image.dart';

void main() {
  final img = Image(width: 300, height: 120);
  fill(img, color: ColorRgb8(255, 255, 255));
  drawBarcode(img, Barcode.code128(), 'Test');
  File('test.png').writeAsBytesSync(encodePng(img));
}
